//! Golden differential tests against the Go implementation (fixtures generated by
//! `go run -mod=vendor ./hack/golden/hostedcluster`, see that file for the scenarios).
//!
//! Each scenario runs the same inputs through the Rust managers on `ctrlrt-fake`, records every
//! create/update/delete call (the object body as sent to the API server, i.e. with
//! apiVersion/kind), the result, the error message, emitted events and conditions, and
//! compares them with the Go recording:
//! * call sequence (verb, kind, namespace, name): exact;
//! * object bodies: JSON-value equality; for hypershift types (HostedCluster, NodePool) the
//!   Go `json.Marshal` bytes are compared byte-for-byte as well (k8s-openapi types such as
//!   Secret serialize their fields in a different order, so only the value is compared);
//! * result (`RequeueAfter` as Go duration string), error string, events: exact.
//!
//! Normalizations (same as the Go generator): HostedCluster `spec.infraID` must match
//! `<name>-[bcdfghjklmnpqrstvwxz2456789]{5}` and is replaced by `INFRAID`; the ETCD encryption
//! key secret's `data.key` must be 32 bytes and is replaced by `KEY`.

use std::collections::BTreeMap;
use std::sync::{Arc, Mutex};

use apis::go::Duration as GoDuration;
use apis::hypershift::util::ipnet::IPNet;
use apis::hypershift::v1beta1 as hyperv1;
use apis::k8s::core::v1::{LocalObjectReference, ObjectReference};
use apis::provisioning::v1alpha1 as provisioningv1alpha1;
use ctrl_hostedcluster::*;
use ctrlrt::k8s_openapi::ByteString;
use ctrlrt::k8s_openapi::api::core::v1::{Node, NodeAddress, NodeStatus, Secret};
use ctrlrt::k8s_openapi::apimachinery::pkg::apis::meta::v1::{ObjectMeta, OwnerReference, Time};
use ctrlrt::k8s_openapi::jiff::Timestamp;
use ctrlrt::meta;
use ctrlrt::{Client, Ctx, FakeRecorder, ReconcileResult, Recorder};
use ctrlrt_fake::{FakeClientBuilder, InitObject, Reaction, Scheme, obj};
use serde_json::Value;

const CR_NAME: &str = "dpf-hcp";
const CR_NS: &str = "clusters";
const CR_UID: &str = "cr-uid-1234";
const COPY_LABEL: &str = "provisioning.dpu.hcp.io/credential-secret-copy";
const INFRA_ALPHABET: &str = "bcdfghjklmnpqrstvwxz2456789";

// ---------------------------------------------------------------------------------------------
// Recording environment
// ---------------------------------------------------------------------------------------------

#[derive(Debug, Clone, PartialEq)]
struct Action {
    verb: String,
    kind: String,
    namespace: String,
    name: String,
    object: Option<Value>,
    raw: Option<String>,
}

struct Env {
    client: Client,
    recorder: Arc<FakeRecorder>,
    actions: Arc<Mutex<Vec<Action>>>,
}

fn scheme() -> Scheme {
    Scheme::new()
        .with_client_go()
        .register::<provisioningv1alpha1::DPFHCPProvisioner>()
        .register::<hyperv1::HostedCluster>()
        .register::<hyperv1::NodePool>()
}

/// Apply the documented normalizations and render the typed body (value + Go-order bytes
/// for hypershift types).
fn normalize(kind: &str, v: Value) -> (Value, Option<String>) {
    match kind {
        "HostedCluster" => {
            let mut hc: hyperv1::HostedCluster = serde_json::from_value(v).unwrap();
            let name = hc.metadata.name.clone().unwrap_or_default();
            let suffix = hc
                .spec
                .infra_id
                .strip_prefix(&format!("{name}-"))
                .unwrap_or_else(|| panic!("unexpected infraID {}", hc.spec.infra_id));
            assert!(
                suffix.len() == 5 && suffix.chars().all(|c| INFRA_ALPHABET.contains(c)),
                "unexpected infraID {}",
                hc.spec.infra_id
            );
            hc.spec.infra_id = "INFRAID".into();
            (
                serde_json::to_value(&hc).unwrap(),
                Some(serde_json::to_string(&hc).unwrap()),
            )
        }
        "NodePool" => {
            let np: hyperv1::NodePool = serde_json::from_value(v).unwrap();
            (
                serde_json::to_value(&np).unwrap(),
                Some(serde_json::to_string(&np).unwrap()),
            )
        }
        "Secret" => {
            let mut s: Secret = serde_json::from_value(v).unwrap();
            if s.metadata
                .name
                .as_deref()
                .is_some_and(|n| n.ends_with("-etcd-encryption-key"))
            {
                let data = s.data.as_mut().expect("data");
                let key = data.get_mut(hyperv1::AESCBC_KEY_SECRET_KEY).expect("key");
                assert_eq!(key.0.len(), 32, "unexpected etcd key length");
                *key = ByteString(b"KEY".to_vec());
            }
            (serde_json::to_value(&s).unwrap(), None)
        }
        other => panic!("unexpected kind {other}"),
    }
}

fn env(objs: Vec<InitObject>) -> Env {
    let actions: Arc<Mutex<Vec<Action>>> = Arc::default();
    let rec = actions.clone();
    let client = FakeClientBuilder::new()
        .with_scheme(scheme())
        .with_objects(objs)
        .with_reactor("*", "*", move |a| {
            if matches!(a.verb.as_str(), "create" | "update" | "delete") {
                let (object, raw) = match &a.object {
                    Some(v) if a.verb != "delete" => {
                        let (v, raw) = normalize(&a.info.kind, v.clone());
                        (Some(v), raw)
                    }
                    _ => (None, None),
                };
                rec.lock().unwrap().push(Action {
                    verb: a.verb.clone(),
                    kind: a.info.kind.clone(),
                    namespace: a.namespace.clone(),
                    name: a.name.clone(),
                    object,
                    raw,
                });
            }
            Reaction::NotHandled
        })
        .build();
    Env {
        client,
        recorder: Arc::new(FakeRecorder::new(100)),
        actions,
    }
}

impl Env {
    fn recorder(&self) -> Recorder {
        self.recorder.clone() as Recorder
    }
}

fn fixture(name: &str) -> Value {
    let path = format!("{}/tests/fixtures/{name}.json", env!("CARGO_MANIFEST_DIR"));
    let s = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    serde_json::from_str(&s).unwrap()
}

/// Compare a Rust run with the Go fixture `name`; returns the fixture for extra checks.
fn check(name: &str, e: &Env, res: ctrlrt::Result<ReconcileResult>) -> Value {
    let want = fixture(name);
    let (result, error) = match res {
        Ok(r) => (r, String::new()),
        Err(err) => (ReconcileResult::default(), err.to_string()),
    };
    assert_eq!(
        GoDuration(result.requeue_after.as_nanos() as i64).to_string(),
        want["requeueAfter"].as_str().unwrap(),
        "{name}: requeueAfter"
    );
    assert_eq!(error, want["error"].as_str().unwrap(), "{name}: error");

    let got_events = e.recorder.drain();
    let want_events: Vec<String> = serde_json::from_value(want["events"].clone()).unwrap();
    assert_eq!(got_events, want_events, "{name}: events");

    let got = e.actions.lock().unwrap().clone();
    let want_actions = want["actions"].as_array().unwrap();
    let summary = |a: &[Action]| {
        a.iter()
            .map(|a| format!("{} {} {}/{}", a.verb, a.kind, a.namespace, a.name))
            .collect::<Vec<_>>()
    };
    let want_summary: Vec<String> = want_actions
        .iter()
        .map(|a| {
            format!(
                "{} {} {}/{}",
                a["verb"].as_str().unwrap(),
                a["kind"].as_str().unwrap(),
                a["namespace"].as_str().unwrap(),
                a["name"].as_str().unwrap()
            )
        })
        .collect();
    assert_eq!(summary(&got), want_summary, "{name}: actions");

    for (g, w) in got.iter().zip(want_actions) {
        assert_eq!(
            g.object.as_ref(),
            w.get("object"),
            "{name}: body of {} {} differs\n rust: {}\n   go: {}",
            g.verb,
            g.kind,
            serde_json::to_string(&g.object).unwrap(),
            w.get("raw").and_then(Value::as_str).unwrap_or("")
        );
        if let Some(raw) = &g.raw {
            assert_eq!(
                raw,
                w["raw"].as_str().unwrap(),
                "{name}: Go-encoded bytes of {} {} differ",
                g.verb,
                g.kind
            );
        }
    }
    want
}

// ---------------------------------------------------------------------------------------------
// Fixtures (mirroring hack/golden/hostedcluster/main.go)
// ---------------------------------------------------------------------------------------------

fn local_ref(name: &str) -> LocalObjectReference {
    LocalObjectReference {
        name: name.into(),
        ..Default::default()
    }
}

fn base_cr() -> provisioningv1alpha1::DPFHCPProvisioner {
    let mut cr = provisioningv1alpha1::DPFHCPProvisioner {
        metadata: ObjectMeta {
            name: Some(CR_NAME.into()),
            namespace: Some(CR_NS.into()),
            uid: Some(CR_UID.into()),
            generation: Some(2),
            ..Default::default()
        },
        ..Default::default()
    };
    cr.spec.dpu_cluster_ref = provisioningv1alpha1::DPUClusterReference {
        name: "dpu".into(),
        namespace: "dpu-system".into(),
        ..Default::default()
    };
    cr.spec.base_domain = "example.com".into();
    cr.spec.ocp_release_image = "quay.io/openshift-release-dev/ocp-release:4.19.0-multi".into();
    cr.spec.ssh_key_secret_ref = local_ref("my-ssh-key");
    cr.spec.pull_secret_ref = local_ref("my-pull-secret");
    cr
}

fn owner_ref(uid: &str) -> Vec<OwnerReference> {
    vec![OwnerReference {
        api_version: "provisioning.dpu.hcp.io/v1alpha1".into(),
        kind: "DPFHCPProvisioner".into(),
        name: CR_NAME.into(),
        uid: uid.into(),
        controller: Some(true),
        block_owner_deletion: Some(true),
    }]
}

fn data(pairs: &[(&str, &str)]) -> BTreeMap<String, ByteString> {
    pairs
        .iter()
        .map(|(k, v)| (k.to_string(), ByteString(v.as_bytes().to_vec())))
        .collect()
}

fn secret(name: &str, owner: &str, labels: &[(&str, &str)], d: &[(&str, &str)]) -> Secret {
    Secret {
        metadata: ObjectMeta {
            name: Some(name.into()),
            namespace: Some(CR_NS.into()),
            labels: if labels.is_empty() {
                None
            } else {
                Some(
                    labels
                        .iter()
                        .map(|(k, v)| (k.to_string(), v.to_string()))
                        .collect(),
                )
            },
            owner_references: if owner.is_empty() {
                None
            } else {
                Some(owner_ref(owner))
            },
            ..Default::default()
        },
        type_: Some("Opaque".into()),
        data: Some(data(d)),
        ..Default::default()
    }
}

fn node(name: &str, addrs: &[(&str, &str)]) -> Node {
    Node {
        metadata: ObjectMeta {
            name: Some(name.into()),
            ..Default::default()
        },
        status: Some(NodeStatus {
            addresses: Some(
                addrs
                    .iter()
                    .map(|(t, a)| NodeAddress {
                        type_: t.to_string(),
                        address: a.to_string(),
                    })
                    .collect(),
            ),
            ..Default::default()
        }),
        ..Default::default()
    }
}

fn owned_hc(
    cr: &provisioningv1alpha1::DPFHCPProvisioner,
    owner: &str,
    pull: &str,
    ssh: &str,
) -> hyperv1::HostedCluster {
    let mut hc = hyperv1::HostedCluster {
        metadata: ObjectMeta {
            name: Some(CR_NAME.into()),
            namespace: Some(CR_NS.into()),
            owner_references: Some(owner_ref(owner)),
            ..Default::default()
        },
        ..Default::default()
    };
    hc.spec.release.image = cr.spec.ocp_release_image.clone();
    hc.spec.infra_id = "dpf-hcp-bcdfg".into();
    hc.spec.pull_secret = local_ref(pull);
    hc.spec.ssh_key = local_ref(ssh);
    hc
}

fn owned_np(owner: &str) -> hyperv1::NodePool {
    let mut np = hyperv1::NodePool {
        metadata: ObjectMeta {
            name: Some(CR_NAME.into()),
            namespace: Some(CR_NS.into()),
            owner_references: Some(owner_ref(owner)),
            ..Default::default()
        },
        ..Default::default()
    };
    np.spec.cluster_name = CR_NAME.into();
    np.spec.release.image = "img".into();
    np
}

const PULL_DATA: &[(&str, &str)] = &[(
    ".dockerconfigjson",
    r#"{"auths":{"quay.io":{"auth":"Zm9vOmJhcg=="}}}"#,
)];
const SSH_DATA: &[(&str, &str)] = &[("id_rsa.pub", "ssh-rsa AAAAB3NzaC1yc2E user@host")];
const KEY_DATA: &[(&str, &str)] = &[("key", "k")];

fn ctx() -> Ctx {
    Ctx::background()
}

