#[tokio::test]
async fn golden_etcd_key_is_random() {
    // Two generated keys differ (crypto/rand), both 32 bytes.
    let mut keys = Vec::new();
    for _ in 0..2 {
        let e = env(vec![]);
        SecretManager::new(e.client.clone())
            .generate_etcd_encryption_key(&ctx(), &base_cr())
            .await
            .unwrap();
        let s: Secret = e
            .client
            .get_named(CR_NS, "dpf-hcp-etcd-encryption-key")
            .await
            .unwrap();
        let key = s.data.unwrap().remove("key").unwrap().0;
        assert_eq!(key.len(), 32);
        keys.push(key);
    }
    assert_ne!(keys[0], keys[1]);
}

