async fn run_finalizer(name: &str, objs: Vec<InitObject>) {
    let e = env(objs);
    let mut m = ctrl_finalizer::Manager::new(e.client.clone(), e.recorder());
    m.register_handler(CleanupHandler::new(e.client.clone(), e.recorder()));
    let res = m.handle_finalizer_cleanup(&ctx(), &base_cr()).await;
    check(name, &e, res);
}

