// ---------------------------------------------------------------------------------------------
// StatusSyncer
// ---------------------------------------------------------------------------------------------

#[tokio::test]
async fn golden_status_sync() {
    let mut cr = base_cr();
    cr.status.hosted_cluster_ref = Some(ObjectReference {
        name: CR_NAME.into(),
        namespace: CR_NS.into(),
        ..Default::default()
    });
    let mut old = meta::condition_gen(
        provisioningv1alpha1::HOSTED_CLUSTER_AVAILABLE,
        meta::CONDITION_FALSE,
        "Old",
        "old",
        1,
    );
    old.last_transition_time = meta::now();
    cr.status.conditions = vec![old];

    let mut hc = owned_hc(&cr, CR_UID, "a", "b");
    for (i, t) in [
        hyperv1::HOSTED_CLUSTER_AVAILABLE,
        hyperv1::HOSTED_CLUSTER_PROGRESSING,
        hyperv1::HOSTED_CLUSTER_DEGRADED,
        hyperv1::VALID_RELEASE_INFO,
        hyperv1::VALID_RELEASE_IMAGE,
        hyperv1::IGNITION_ENDPOINT_AVAILABLE,
        hyperv1::IGNITION_SERVER_VALID_RELEASE_INFO,
        hyperv1::INFRASTRUCTURE_READY,
    ]
    .iter()
    .enumerate()
    {
        let mut c = meta::condition(
            *t,
            meta::CONDITION_TRUE,
            format!("Reason{i}"),
            format!("message {i}"),
        );
        c.last_transition_time = meta::now();
        hc.status.conditions.push(c);
    }

    let e = env(vec![obj(&hc)]);
    let res = StatusSyncer::new(e.client.clone())
        .sync_status_from_hosted_cluster(&ctx(), &mut cr)
        .await;
    let want = check("status_sync", &e, res);

    let mut got: Vec<Value> = cr
        .status
        .conditions
        .iter()
        .map(|c| {
            serde_json::json!({
                "type": c.type_,
                "status": c.status,
                "reason": c.reason,
                "message": c.message,
                "observedGeneration": c.observed_generation.unwrap_or(0),
            })
        })
        .collect();
    // Go mirrors in map order; compare sorted by type.
    got.sort_by(|a, b| a["type"].as_str().cmp(&b["type"].as_str()));
    assert_eq!(Value::Array(got), want["conditions"]);
}

