// PullSecretCopyName / SSHKeyCopyName
// ---------------------------------------------------------------------------------------------

#[test]
fn golden_copy_names() {
    let want = fixture("copy_names");
    for entry in want.as_array().unwrap() {
        let r = entry["ref"].as_str().unwrap();
        let mut cr = base_cr();
        cr.spec.pull_secret_ref.name = r.into();
        cr.spec.ssh_key_secret_ref.name = r.into();
        assert_eq!(
            pull_secret_copy_name(&cr),
            entry["pull"].as_str().unwrap(),
            "{r}"
        );
        assert_eq!(
            ssh_key_copy_name(&cr),
            entry["ssh"].as_str().unwrap(),
            "{r}"
        );
    }
}
